                .map(this::mapToDTO)
                .collect(Collectors.toList());
    }

    // Get all active patients
    public List<PatientDTO> getActivePatients() {
        return patientRepository.findByActiveTrue().stream()
                .map(this::mapToDTO)
                .collect(Collectors.toList());
    }

    // Deactivate patient
    @Transactional
    public PatientDTO deactivatePatient(Long patientId) {
